def find_cycles_of_length_k(adj, k):
    """Find if there's a cycle of length k"""
    # BFS from each vertex to find cycles
    for start in range(n):
        # BFS with path tracking
        queue = [(start, [start])]
        visited_at_depth = {start: 0}
        while queue:
            node, path = queue.pop(0)
            if len(path) > k:
                continue
            for neighbor in adj[node]:
                if neighbor == start and len(path) == k:
                    return True  # Found cycle of length k
                if neighbor not in visited_at_depth or visited_at_depth[neighbor] > len(path):
                    if len(path) < k:
                        visited_at_depth[neighbor] = len(path)
                        queue.append((neighbor, path + [neighbor]))
    return False

def has_short_cycle(adj, max_len=6):
    """Check if graph has any cycle of length 3 to max_len"""
    for k in range(3, max_len+1):
        if find_cycles_of_length_k(adj, k):
            return True
    return False

